INSERT INTO public.reading_sets (
    set_id, title, title_zh, grade, difficulty, topic, passage,
    word_count, estimated_minutes, sort_order, version, updated_at
) VALUES (
    'r08-02',
    $seedie$Why Sleep Matters for Teenagers$seedie$,
    $seedie$为什么睡眠对青少年很重要$seedie$,
    8,
    $seedie$medium$seedie$,
    $seedie$health_science$seedie$,
    $seedie$Many teenagers say they feel tired at school. Some stay up late to finish homework. Others watch short videos until midnight. They may think, "I can sleep less now and rest more on weekends." But scientists say this idea is not helpful.

Sleep is not just "doing nothing." While we sleep, the brain sorts information from the day. It helps us remember what we learned. It also repairs the body and supports a healthy mood. For most teenagers, experts suggest about eight to ten hours of sleep each night. When sleep is too short, students may find it harder to focus in class. They may also get angry more easily or catch colds more often.

Why is it difficult for teenagers to sleep early? One reason is biological. During the teenage years, the body clock often shifts later. That means many teens do not feel sleepy until later in the evening. Another reason is lifestyle. Bright screens before bed can <<trick>> the brain into thinking it is still daytime. Heavy homework and worry can also keep the mind busy.

What can students do? First, keep a regular bedtime, even on weekends when possible. Second, put phones away at least thirty minutes before sleep. Third, do quiet activities such as reading a paper book or listening to soft music. Finally, if stress about tests is too strong, talk with parents or teachers. Better sleep will not solve every problem, but it can make busy school days easier to manage.$seedie$,
    256,
    8,
    1,
    1,
    2026072901
)
