INSERT INTO public.reading_sets (
    set_id, title, title_zh, grade, difficulty, topic, passage,
    word_count, estimated_minutes, sort_order, version, updated_at
) VALUES (
    'r08-03',
    $seedie$The Wallet on the Bus$seedie$,
    $seedie$公交车上的钱包$seedie$,
    8,
    $seedie$easy$seedie$,
    $seedie$values_narrative$seedie$,
    $seedie$On a rainy Monday morning, Lin Hao took Bus 12 to school as usual. The bus was crowded. He held his backpack close and looked out of the wet window. When the bus stopped near the park, an old man stood up and hurried to the door. A moment later, Lin Hao noticed a brown wallet on the empty seat.

Lin Hao picked it up. Inside there was a student ID card, some money, and a small photo of a girl with her grandparents. The name on the card was Zhang Yue. Lin Hao felt nervous. If he did nothing, the owner might lose important things. If he shouted on the busy bus, people might not hear him clearly.

He decided to give the wallet to the bus driver. The driver smiled and said, "Thank you. I will keep it safe and call the school number on the card." After school, Lin Hao's teacher told the class that Zhang Yue from Class 8C had got her wallet back. She had almost cried when she found it missing, because the photo was the only one of her late grandmother.

The next day, Zhang Yue found Lin Hao at the school gate. She did not say many words. She just handed him a handmade thank-you card. Lin Hao felt a little shy, but also proud. He understood that honesty is not always <<dramatic>>. Sometimes it is a quiet choice on an ordinary morning.$seedie$,
    238,
    7,
    2,
    1,
    2026072901
)
